begin;
select no_plan();
insert into auth.users(id,email) values ('aaaabbbb-1111-4111-8111-111111111111','advisor-test@example.test'),('bbbbcccc-2222-4222-8222-222222222222','other-advisor@example.test');
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaabbbb-1111-4111-8111-111111111111',true);
insert into public.clients(id,name,herd_number,county,phone,email) values ('ccccdddd-3333-4333-8333-333333333333','Fictional farmer','DEMO-ADVISOR','Cork','0000000000','farmer@example.test');
insert into public.rates(id,name,unit,price_cents) values ('ddddeeee-4444-4444-8444-444444444444','Review','hour',7500);
select lives_ok($$select public.recommend_work('eeeeffff-5555-4555-8555-555555555555','ccccdddd-3333-4333-8333-333333333333','Review farm records','ddddeeee-4444-4444-8444-444444444444',2)$$,'advisor recommends two hours');
select is((select estimate_cents from public.work_recommendations),15000::bigint,'estimate is quantity times rate');
select is((select status from public.jobs),'planned','recommendation creates planned work only');
select lives_ok($$select public.recommend_work('eeeeffff-5555-4555-8555-555555555555','ccccdddd-3333-4333-8333-333333333333','Review farm records','ddddeeee-4444-4444-8444-444444444444',2)$$,'recommendation retry is idempotent');
select throws_ok($$select public.recommend_work('eeeeffff-5555-4555-8555-555555555555','ccccdddd-3333-4333-8333-333333333333','Review farm records','ddddeeee-4444-4444-8444-444444444444',3)$$,'23514',null,'changed replay rejected');
select is(public.client_work_balance('ccccdddd-3333-4333-8333-333333333333')->>'owed_cents','0','recommendation creates no debt');
select is(public.client_work_balance('ccccdddd-3333-4333-8333-333333333333')->>'estimated_cents','15000','unbilled estimated work is separate');
select throws_ok($$update public.work_recommendations set quantity=99$$,'42501',null,'estimates cannot be rewritten directly');
select set_config('request.jwt.claim.sub','bbbbcccc-2222-4222-8222-222222222222',true);
select is((select count(*) from public.work_recommendations),0::bigint,'other advisor cannot read recommendations');
select is(public.client_work_balance('ccccdddd-3333-4333-8333-333333333333'),null::jsonb,'other advisor cannot read balance');
select throws_ok($$select public.recommend_work('ffffaaaa-6666-4666-8666-666666666666','ccccdddd-3333-4333-8333-333333333333','Foreign work','ddddeeee-4444-4444-8444-444444444444',2)$$,'42501',null,'other advisor cannot recommend work to this client');
select set_config('request.jwt.claim.sub','aaaabbbb-1111-4111-8111-111111111111',true);
insert into public.billing_profiles(business_name,business_address,vat_registered) values ('Demo advisor business','Fictional address',false);
update public.jobs set status='in_progress'; update public.jobs set status='completed';
select public.create_invoice_draft('aaaaffff-7777-4777-8777-777777777777','eeeeffff-5555-4555-8555-555555555555','ddddeeee-4444-4444-8444-444444444444',2,'Fictional address',current_date,current_date+30,null);
select is(public.client_work_balance('ccccdddd-3333-4333-8333-333333333333')->>'owed_cents','0','draft is not debt');
select is(public.client_work_balance('ccccdddd-3333-4333-8333-333333333333')->>'estimated_cents','0','draft-linked work not double counted as unbilled');
select public.transition_invoice('aaaaffff-7777-4777-8777-777777777777','issue',null);
select is(public.client_work_balance('ccccdddd-3333-4333-8333-333333333333')->>'owed_cents','15000','issued invoice becomes amount owed');
select public.transition_invoice('aaaaffff-7777-4777-8777-777777777777','paid',current_date);
select is(public.client_work_balance('ccccdddd-3333-4333-8333-333333333333')->>'owed_cents','0','full payment removes outstanding balance');
insert into public.rates(id,name,unit,price_cents) values ('bbbbffff-8888-4888-8888-888888888888','Fixed review','fixed',10000);
select throws_ok($$select public.recommend_work('ffffaaaa-6666-4666-8666-666666666666','ccccdddd-3333-4333-8333-333333333333','Fixed work','bbbbffff-8888-4888-8888-888888888888',2)$$,'23514',null,'fixed recommendations require quantity one');
update public.rates set retired=true where id='bbbbffff-8888-4888-8888-888888888888';
select throws_ok($$select public.recommend_work('ffffaaaa-6666-4666-8666-666666666666','ccccdddd-3333-4333-8333-333333333333','Retired work','bbbbffff-8888-4888-8888-888888888888',1)$$,'42501',null,'retired rates cannot be recommended');
update public.clients set archived_at=clock_timestamp();
select throws_ok($$select public.recommend_work('ffffaaaa-6666-4666-8666-666666666666','ccccdddd-3333-4333-8333-333333333333','Archived work','ddddeeee-4444-4444-8444-444444444444',2)$$,'42501',null,'archived clients cannot receive new recommendations');
set local role anon;
select throws_ok($$select public.client_work_balance('ccccdddd-3333-4333-8333-333333333333')$$,'42501',null,'anonymous balance denied');
select throws_ok($$select public.recommend_work('ffffaaaa-6666-4666-8666-666666666666','ccccdddd-3333-4333-8333-333333333333','Anonymous work','ddddeeee-4444-4444-8444-444444444444',2)$$,'42501',null,'anonymous recommendations denied');
select * from finish();
rollback;
